from collections import Counter
import json
home=Path.home()
p=home/'Downloads'
if not p.is_dir():
    print(json.dumps({'home':str(home),'downloads_exists':False,'home_directories':[x.name for x in home.iterdir() if x.is_dir() and not x.name.startswith('.')]},ensure_ascii=False))
else:
    files=[]; dirs=[]; errors=[]; hidden=[]
    for x in p.iterdir():
        if x.name.startswith('.'):
            hidden.append(x.name)
            continue
        try:
            if x.is_symlink():
                errors.append({'name':x.name,'note':'符号链接，未跟随'})
            elif x.is_file():
                s=x.stat()
