from pathlib import Path
import time, datetime, json
folder = Path.home() / 'Downloads'
if not folder.is_dir():
    raise FileNotFoundError(f'下载目录不存在：{folder}')
def snapshot():
    return {p.name for p in folder.iterdir()}
def stamp():
    return datetime.datetime.now().astimezone().isoformat(timespec='seconds')
previous = snapshot()
start = time.monotonic()
print(json.dumps({'baseline_time': stamp(), 'folder': str(folder), 'initial_entries': sorted(previous)}, ensure_ascii=False), flush=True)
for i in range(1, 5):
    time.sleep(max(0, start + 20*i - time.monotonic()))
    current = snapshot()
    print(json.dumps({'check': i, 'time': stamp(), 'elapsed_seconds': round(time.monotonic()-start, 1), 'added': sorted(current-previous), 'deleted': sorted(previous-current), 'entry_count': len(current)}, ensure_ascii=False), flush=True)
    previous = current

