from pathlib import Path
import time, datetime, json
folder = Path.home() / 'Downloads'
if not folder.is_dir():
    print(json.dumps({'error':'Downloads folder not found','path':str(folder)}, ensure_ascii=False))
else:
    samples=[]
    start=time.monotonic()
    for i in range(4):
        delay=start+i*20-time.monotonic()
        if delay>0: time.sleep(delay)
        entries={p.name: ('directory' if p.is_dir() else 'file') for p in folder.iterdir()}
        sample={'check':i+1,'time':datetime.datetime.now().astimezone().isoformat(timespec='seconds'),'entries':entries}
        samples.append(sample)
        print(json.dumps({'check':i+1,'time':sample['time'],'item_count':len(entries)},ensure_ascii=False), flush=True)
    changes=[]
    for prev,cur in zip(samples,samples[1:]):
        a,b=prev['entries'],cur['entries']
        changes.append({'between':[prev['check'],cur['check']],'added':sorted(set(b)-set(a)),'removed':sorted(set(a)-set(b))})
    print(json.dumps({'path':str(folder),'start':samples[0]['time'],'end':samples[-1]['time'],'elapsed_seconds':round(time.monotonic()-start,1),'changes':changes,'net_added':sorted(set(samples[-1]['entries'])-set(samples[0]['entries'])),'net_removed':sorted(set(samples[0]['entries'])-set(samples[-1]['entries']))},ensure_ascii=False))

