from pathlib import Path
import json
mem = Path('../memory/global_mem.txt')
print('MEMORY:', mem.read_text() if mem.exists() else '(not present)')
d = Path.home() / 'Downloads'
print('DOWNLOADS:', d)
if not d.is_dir():
    print('ERROR: Downloads directory not found')
else:
    groups = {}
    dirs = []
    for p in sorted(d.iterdir(), key=lambda p: p.name.casefold()):
        if p.name.startswith('.'):
            continue
        if p.is_dir():
            dirs.append(p.name)
        else:
            ext = p.suffix.lower() or '(无扩展名)'
            groups.setdefault(ext, []).append(p.name)
    print(json.dumps({'types': groups, 'folders': dirs, 'file_count': sum(map(len, groups.values())), 'folder_count': len(dirs), 'scope': '仅顶层、不含隐藏项目'}, ensure_ascii=False, indent=2))

