from pathlib import Path
from collections import defaultdict
import json
folder = Path.home() / 'Downloads'
image_exts = {'.jpg','.jpeg','.png','.gif','.webp','.heic','.heif','.avif','.bmp','.tif','.tiff','.svg','.ico','.raw','.cr2','.cr3','.nef','.arw','.dng'}
if not folder.is_dir():
    print(json.dumps({'path':str(folder),'exists':False},ensure_ascii=False))
else:
    groups=defaultdict(list)
    for p in sorted(folder.iterdir(), key=lambda p:p.name.casefold()):
        if p.is_file():
            ext=p.suffix.lower()
            if ext == '.pdf' or ext in image_exts:
                groups[ext].append(p.name)
    print(json.dumps({'path':str(folder),'scope':'top-level files only','files':dict(groups),'pdf_count':len(groups.get('.pdf',[])),'image_count':sum(len(v) for k,v in groups.items() if k in image_exts)},ensure_ascii=False,indent=2))

