from pathlib import Path
import time, json
from datetime import datetime
folder=Path.home()/'Downloads'
def snapshot():
    return {p.name: ('directory' if p.is_dir() else 'file') for p in folder.iterdir()}
def now(): return datetime.now().astimezone().isoformat(timespec='seconds')
baseline=snapshot()
print(json.dumps({'phase':'baseline','time':now(),'path':str(folder),'entries':baseline},ensure_ascii=False),flush=True)
previous=baseline
start=time.monotonic()
for n in range(1,5):
    time.sleep(max(0,start+20*n-time.monotonic()))
    current=snapshot()
